<?php
/**
 * IMPORT: Elementor Footer Template aktualisieren.
 *
 * Erst DRY_RUN = true auf einer Test-Region.
 * Danach DRY_RUN = false auf derselben Test-Region.
 */

defined('ABSPATH') || exit;

const MYCITY_FOOTER_IMPORT_DRY_RUN = true;

$footer_payload_b64 = '';

echo '<pre>';

echo MYCITY_FOOTER_IMPORT_DRY_RUN
    ? "DRY RUN - Es wird nichts gespeichert.\n\n"
    : "LIVE RUN - Footer wird aktualisiert.\n\n";

$json = base64_decode(trim($footer_payload_b64), true);

if ($json === false) {
    echo "FEHLER: Footer Payload konnte nicht decodiert werden.\n";
    echo '</pre>';
    return;
}

$data = json_decode($json, true);

if (!is_array($data)) {
    echo "FEHLER: Footer Payload ist kein gültiges JSON.\n";
    echo '</pre>';
    return;
}

$existing = get_page_by_path('footer', OBJECT, 'elementor_library');

if (!$existing) {
    $found = get_posts([
        'post_type'      => 'elementor_library',
        'post_status'    => ['publish', 'draft', 'private'],
        'title'          => 'Footer',
        'posts_per_page' => 1,
    ]);

    $existing = $found[0] ?? null;
}

$postarr = [
    'post_title'   => 'Footer',
    'post_name'    => 'footer',
    'post_content' => $data['post_content'] ?? '',
    'post_excerpt' => $data['post_excerpt'] ?? '',
    'post_status'  => 'publish',
    'post_type'    => 'elementor_library',
];

if ($existing) {
    $postarr['ID'] = $existing->ID;
    echo "Vorhandener Footer gefunden.\n";
    echo "ID: {$existing->ID}\n";
    echo "Aktion: Footer wird überschrieben.\n\n";
} else {
    echo "Kein Footer gefunden.\n";
    echo "Aktion: Footer wird neu angelegt.\n\n";
}

if (MYCITY_FOOTER_IMPORT_DRY_RUN) {
    echo "STATUS: Nur Testlauf.\n";
    echo '</pre>';
    return;
}

if ($existing) {
    $template_id = wp_update_post(wp_slash($postarr), true);
} else {
    $template_id = wp_insert_post(wp_slash($postarr), true);
}

if (is_wp_error($template_id)) {
    echo "FEHLER beim Speichern:\n";
    echo $template_id->get_error_message();
    echo '</pre>';
    return;
}

$meta_keys_to_clear = [
    '_elementor_data',
    '_elementor_edit_mode',
    '_elementor_template_type',
    '_elementor_version',
    '_elementor_page_settings',
    '_elementor_css',
];

foreach ($meta_keys_to_clear as $meta_key) {
    delete_post_meta($template_id, $meta_key);
}

if (!empty($data['meta']) && is_array($data['meta'])) {
    foreach ($data['meta'] as $meta_key => $meta_value) {
        if (is_string($meta_value)) {
            update_post_meta($template_id, $meta_key, wp_slash($meta_value));
        } else {
            update_post_meta($template_id, $meta_key, $meta_value);
        }

        echo "Meta gespeichert: {$meta_key}\n";
    }
}

update_post_meta($template_id, '_elementor_edit_mode', 'builder');

if (!get_post_meta($template_id, '_elementor_template_type', true)) {
    update_post_meta($template_id, '_elementor_template_type', 'footer');
}

/**
 * Widerrufsrecht-Link sicher relativ setzen.
 */
$elementor_data = get_post_meta($template_id, '_elementor_data', true);

if (is_string($elementor_data) && $elementor_data !== '') {
    $elementor_data = str_replace(
        [
            'https://wl.trolleymaker-test.de/widerrufsrecht/',
            'https://wl.trolleymaker-test.de/widerrufsrecht',
            'http://wl.trolleymaker-test.de/widerrufsrecht/',
            'http://wl.trolleymaker-test.de/widerrufsrecht',
        ],
        '/widerrufsrecht/',
        $elementor_data
    );

    update_post_meta($template_id, '_elementor_data', wp_slash($elementor_data));
}

clean_post_cache($template_id);

if (class_exists('\Elementor\Plugin')) {
    try {
        \Elementor\Plugin::$instance->files_manager->clear_cache();

        if (class_exists('\Elementor\Core\Files\CSS\Post')) {
            $css_file = new \Elementor\Core\Files\CSS\Post($template_id);
            $css_file->update();
        }

        echo "\nElementor Cache/CSS erneuert.\n";
    } catch (Throwable $e) {
        echo "\nHinweis: Elementor Cache konnte nicht vollständig erneuert werden.\n";
    }
}

echo "\nFERTIG: Footer aktualisiert.\n";
echo '</pre>';